pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testFuzz_property(address account, uint256 id) public {
        vm.assume(account != address(0));
        uint256 balance = c.balanceOf(account, id);
        uint256 balanceNext = c.balanceOf(account, id + 1);
        assertTrue(balance == balanceNext);
    }
}
